#include "document.h"
namespace moon {
void Document::selectSlice(const std::string& id,bool additive){const bool exists=std::any_of(slices().begin(),slices().end(),[&](const auto& s){return s.id==id;});if(!additive){sliceState_.selected=exists?std::vector<std::string>{id}:std::vector<std::string>{};return;}if(!exists)return;auto& values=sliceState_.selected;auto it=std::find(values.begin(),values.end(),id);if(it==values.end())values.push_back(id);else values.erase(it);}
void Document::selectAllSlices(){sliceState_.selected.clear();for(const auto& s:slices())sliceState_.selected.push_back(s.id);}
void Document::setImportedSlices(std::vector<DocumentSlice> values){sliceState_.items=normalizeDocumentSlices(std::move(values),width_,height_);sliceState_.selected.clear();}
bool Document::commitSlices(SliceState next,std::u32string label){if(next.items==sliceState_.items)return false;next.selected.erase(std::remove_if(next.selected.begin(),next.selected.end(),[&](const auto& id){return std::none_of(next.items.begin(),next.items.end(),[&](const auto& s){return s.id==id;});}),next.selected.end());Edit e{{},state_,nextState_};e.beforeSlices=sliceState_;e.afterSlices=std::move(next);history_.reserve(position_+1);change_={};applyEdit(e,true);pushEdit(std::move(e),std::move(label));return true;}
bool Document::createSlices(const std::vector<SliceRect>& rects){if(rects.empty())return false;auto next=sliceState_;next.selected.clear();for(auto r:rects){std::string id;do{id="slice-native-"+std::to_string(identity_)+"-"+std::to_string(++nextSliceId_);}while(std::any_of(next.items.begin(),next.items.end(),[&](const auto& s){return s.id==id;}));const auto n=std::to_string(next.items.size()+1);next.items.push_back({id,U"切片 "+std::u32string(n.begin(),n.end()),clampSliceRect(r,width_,height_)});next.selected.push_back(id);}return commitSlices(std::move(next),rects.size()>1?U"自动创建切片":U"创建切片");}
bool Document::updateSlices(const std::vector<DocumentSlice>& patches){auto next=sliceState_;for(const auto& p:patches){auto it=std::find_if(next.items.begin(),next.items.end(),[&](const auto& s){return s.id==p.id;});if(it==next.items.end())continue;it->rect=clampSliceRect(p.rect,width_,height_);it->name=sanitizeSliceName(p.name,it->name);}return commitSlices(std::move(next),U"调整切片");}
bool Document::duplicateSlices(const std::vector<DocumentSlice>& targets){auto next=sliceState_;next.selected.clear();for(const auto& target:targets){const auto it=std::find_if(slices().begin(),slices().end(),[&](const auto& s){return s.id==target.id;});if(it==slices().end())continue;auto copy=*it;do{copy.id="slice-native-"+std::to_string(identity_)+"-"+std::to_string(++nextSliceId_);}while(std::any_of(next.items.begin(),next.items.end(),[&](const auto& s){return s.id==copy.id;}));copy.rect=clampSliceRect(target.rect,width_,height_);next.selected.push_back(copy.id);next.items.push_back(std::move(copy));}return commitSlices(std::move(next),U"复制切片");}
bool Document::deleteSlices(const std::vector<std::string>& ids){auto next=sliceState_;next.items.erase(std::remove_if(next.items.begin(),next.items.end(),[&](const auto& s){return std::find(ids.begin(),ids.end(),s.id)!=ids.end();}),next.items.end());return commitSlices(std::move(next),U"删除切片");}
}
